import{_ as o,o as t,c as e,a2 as r}from"./chunks/framework.DxR7mb1F.js";const i="/bluebook/community/contacts/liu-cong-nlp.jpg",l="/bluebook/community/contacts/dai-shu-di.jpg",n="/bluebook/community/contacts/jia-mu.jpg",s="/bluebook/community/contacts/joy.jpg",_=JSON.parse('{"title":"参与共创","description":"WorkBuddy 的能力、界面和使用方式会持续变化。这本蓝皮书希望由真实使用者共同维护：不仅纠正事实，也不断补充可复现的任务、失败经验和团队方法。 如果你已经用 WorkBuddy 跑通了一项真实任务，推荐优先提交到社区案例集…","frontmatter":{},"headers":[],"relativePath":"community/contributing.md","filePath":"community/contributing.md","lastUpdated":1786808975000}'),c={name:"community/contributing.md"};function d(u,a,m,h,p,b){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="参与共创" tabindex="-1">参与共创 <a class="header-anchor" href="#参与共创" aria-label="Permalink to &quot;参与共创&quot;">​</a></h1><p>WorkBuddy 的能力、界面和使用方式会持续变化。这本蓝皮书希望由真实使用者共同维护：不仅纠正事实，也不断补充可复现的任务、失败经验和团队方法。</p><h2 id="可以贡献什么" tabindex="-1">可以贡献什么 <a class="header-anchor" href="#可以贡献什么" aria-label="Permalink to &quot;可以贡献什么&quot;">​</a></h2><ul><li>修正错别字、失效链接、过时界面和不准确表述。</li><li>补充一个真实、可复现的 WorkBuddy 案例。</li><li>为现有案例增加输入、输出、验收标准和失败处理。</li><li>补充岗位或行业工作流。</li><li>改进截图、图表、导航和无障碍体验。</li></ul><h2 id="提交社区-case" tabindex="-1">提交社区 Case <a class="header-anchor" href="#提交社区-case" aria-label="Permalink to &quot;提交社区 Case&quot;">​</a></h2><p>如果你已经用 WorkBuddy 跑通了一项真实任务，推荐优先提交到<a href="/bluebook/cases/">社区案例集</a>。每个 Case 需要说明使用场景、使用的 Skills、在 WorkBuddy 中的操作、最终效果和验收标准。</p><p>请先阅读<a href="/bluebook/community/case-contributing">Case 投稿指南</a>。PR 合并后，案例会自动显示在网站的案例集合页；经过进一步复现和编辑的经典任务，未来可能进入蓝皮书正文。</p><h2 id="最轻量的方式-提交-issue" tabindex="-1">最轻量的方式：提交 Issue <a class="header-anchor" href="#最轻量的方式-提交-issue" aria-label="Permalink to &quot;最轻量的方式：提交 Issue&quot;">​</a></h2><p>如果暂时不想修改文件，可以在 <a href="https://github.com/AlephAITech/WorkBuddyGuide/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 中说明：</p><ol><li>哪一页需要调整。</li><li>现在的问题是什么。</li><li>建议怎样修改。</li><li>如果涉及产品事实，请附上来源或截图。</li></ol><h2 id="直接修改内容" tabindex="-1">直接修改内容 <a class="header-anchor" href="#直接修改内容" aria-label="Permalink to &quot;直接修改内容&quot;">​</a></h2><ol><li>Fork 或克隆仓库。</li><li>找到 <code>docs/bluebook/</code> 下对应章节的 <code>index.md</code>。</li><li>修改内容或在同目录的 <code>assets/</code> 中补充素材。</li><li>本地运行 <code>npm install</code> 和 <code>npm run docs:build</code>。</li><li>提交 Pull Request，并说明改动、原因和验证方式。</li></ol><p>完整规范见仓库根目录的 <a href="https://github.com/AlephAITech/WorkBuddyGuide/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>。</p><h2 id="内容原则" tabindex="-1">内容原则 <a class="header-anchor" href="#内容原则" aria-label="Permalink to &quot;内容原则&quot;">​</a></h2><ul><li><strong>真实任务优先</strong>：说明输入、步骤、交付物和验收方式。</li><li><strong>事实与经验分开</strong>：产品事实尽量附来源；个人经验说明适用条件。</li><li><strong>对新手友好</strong>：不要假设读者知道工具、权限和术语。</li><li><strong>安全边界清晰</strong>：涉及文件、账号、密钥、发布和外部操作时说明风险。</li><li><strong>尊重隐私与版权</strong>：不要提交密钥、个人数据或无权公开的资料。</li></ul><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>如果你想交流共创想法、提交案例，或者参与蓝皮书后续维护，可以扫描二维码联系我们。点击图片可查看大图。</p><div class="wb-contact-grid"><a class="wb-contact-card" href="/community/contacts/liu-cong-nlp.jpg" target="_blank" rel="noreferrer"><img src="'+i+'" alt="刘聪NLP 微信二维码" loading="lazy"><span>刘聪NLP</span></a><a class="wb-contact-card" href="/community/contacts/dai-shu-di.jpg" target="_blank" rel="noreferrer"><img src="'+l+'" alt="袋鼠帝微信二维码" loading="lazy"><span>袋鼠帝</span></a><a class="wb-contact-card" href="/community/contacts/jia-mu.jpg" target="_blank" rel="noreferrer"><img src="'+n+'" alt="甲木微信二维码" loading="lazy"><span>甲木</span></a><a class="wb-contact-card" href="/community/contacts/joy.jpg" target="_blank" rel="noreferrer"><img src="'+s+'" alt="Joy 微信二维码" loading="lazy"><span>Joy</span></a></div>',18)])])}const k=o(c,[["render",d]]);export{_ as __pageData,k as default};
